try:
    print('>>> f = hasattr')
    print('>>> x = 2.3456')
    print('>>> y = set()')
    print('>>> f(x, y)')
    f = hasattr
    x = 2.3456
    y = set()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
